class DeviceNameNotProvided(Exception):
    """ When no device name is provided to work on."""
    pass


class InvalidDeviceName(Exception):
    def __init__(self, device_name, device_list):
        self._device_name = device_name
        self._device_list = device_list

    def __str__(self):
        return 'Device "{}" not in supported list: {}'.format(self._device_name, self._device_list)


class InvalidChromePreferences(Exception):
    """ When chrome preferences is invalid to work on."""
    pass
